// src/components/ActivityLog.js
import React, { useEffect, useState } from "react";

export default function ActivityLog() {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchLogs();
  }, []);

  const fetchLogs = async () => {
    try {
      const response = await fetch("http://127.0.0.1:8000/api/mongo_activity_logs/", {
        method: "GET",
        headers: {
          "Content-Type": "application/json",
          // If you use JWT authentication, add Authorization header:
          // "Authorization": `Bearer ${localStorage.getItem("token")}`,
        },
      });
      const data = await response.json();
      setLogs(data);
      setLoading(false);
    } catch (error) {
      console.error("Error fetching activity logs:", error);
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Activity Log</h2>
      {loading ? (
        <p>Loading...</p>
      ) : (
        <table style={{ width: "100%", borderCollapse: "collapse" }}>
          <thead>
            <tr>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>User ID</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Action</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Model</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Object ID</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Details</th>
              <th style={{ border: "1px solid #ccc", padding: "8px" }}>Timestamp</th>
            </tr>
          </thead>
          <tbody>
            {logs.map((log) => (
              <tr key={log._id}>
                <td style={{ border: "1px solid #ccc", padding: "8px" }}>{log.user_id}</td>
                <td style={{ border: "1px solid #ccc", padding: "8px" }}>{log.action}</td>
                <td style={{ border: "1px solid #ccc", padding: "8px" }}>{log.model_name}</td>
                <td style={{ border: "1px solid #ccc", padding: "8px" }}>{log.object_id}</td>
                <td style={{ border: "1px solid #ccc", padding: "8px" }}>
                  {log.details ? JSON.stringify(log.details) : ""}
                </td>
                <td style={{ border: "1px solid #ccc", padding: "8px" }}>{new Date(log.timestamp).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}
